package net.minecraft.world.chunk;
import java.util.*; import net.minecraft.block.*; import net.minecraft.block.state.*; import net.minecraft.init.Blocks; import net.minecraft.util.math.BlockPos; import net.minecraft.world.biome.Biome; import net.minecraft.tileentity.TileEntity; public class Chunk { public final int x,z; public Biome biome; public Block top=Blocks.DIRT; public int[][] h=new int[16][16]; public Map<BlockPos,IBlockState> overlay=new HashMap<>(); public Map<BlockPos,TileEntity> tiles=new HashMap<>(); public Chunk(int x,int z,Biome b,int height){this.x=x;this.z=z;biome=b;for(int[] row:h)Arrays.fill(row,height);} public Biome getBiome(BlockPos p,Object provider){return biome;} public int getHeightValue(int x,int z){return h[x][z];} public IBlockState getBlockState(int x,int y,int z){return getBlockState(new BlockPos((this.x<<4)+(x&15),y,(this.z<<4)+(z&15)));} public IBlockState getBlockState(BlockPos p){ IBlockState s=overlay.get(p); if(s!=null)return s; int height=h[p.getX()&15][p.getZ()&15]; return (p.getY()==height-1?top:p.getY()<height-1?Blocks.DIRT:Blocks.AIR).getDefaultState(); } public Map<BlockPos,TileEntity> getTileEntityMap(){return tiles;} }